SourceCode.Declaration:
/// <summary>
/// Attribute class used for indicating content-type
/// </summary>
public class TFMContentTypeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TFMDocumentContentSubject   contentType;

}

Method.Source:
public TFMDocumentContentSubject parmContentType(TFMDocumentContentSubject _contentType = contentType)
{
    contentType = _contentType;

    return contentType;
}
